mapper.select:
SELECT b.bill_month AS billMonth, b.currency AS currency, b.status AS status,
       COALESCE(SUM(b.total_amount), 0) AS amount
FROM wms_monthly_bill b

    b.deleted = 0
    AND b.wms_tenant_id = #{wmsTenantId}

        AND b.bill_month >= #{monthStart}


        AND b.bill_month <= #{monthEnd}


GROUP BY b.bill_month, b.currency, b.status

SELECT o.erp_tenant_id AS erpTenantId,
       t.tenant_name AS ownerName,
       COUNT(*) AS orders
FROM wms_fulfillment_order o
INNER JOIN sys_tenant t ON t.id = o.erp_tenant_id AND t.parent_wms_tenant_id = #{wmsTenantId}

    o.deleted = 0
    AND o.wms_tenant_id = #{wmsTenantId}
    AND o.fulfillment_status = 'SHIPPED'
    AND o.shipped_time IS NOT NULL

        AND DATE(CONVERT_TZ(o.shipped_time, '+08:00', '+03:00')) >= #{dateStart}


        AND DATE(CONVERT_TZ(o.shipped_time, '+08:00', '+03:00')) <= #{dateEnd}


        AND o.erp_tenant_id IN
        #{e}


GROUP BY o.erp_tenant_id, t.tenant_name
ORDER BY orders DESC
LIMIT 10

SELECT COALESCE(SUM(i.quantity), 0)
FROM wms_location_inventory i
INNER JOIN wms_warehouse w ON w.id = i.warehouse_id
    AND w.warehouse_type = 'OWN' AND w.deleted = 0
INNER JOIN sys_tenant t ON t.id = i.erp_tenant_id AND t.parent_wms_tenant_id = #{wmsTenantId}

    i.wms_tenant_id = #{wmsTenantId}
    AND i.deleted = 0
    AND i.quantity > 0

        AND i.erp_tenant_id IN
        #{e}

SELECT COUNT(*) AS cnt, COALESCE(SUM(monthly_fee), 0) AS fee
FROM wms_rack_assignment
WHERE wms_tenant_id = #{wmsTenantId}
  AND effective_from <= #{today}
  AND (effective_to IS NULL OR effective_to >= #{today})
